    public static object ProcessFunctionResult(object functionResult)
    {
        if (functionResult is string stringResult)
        {
            return stringResult;
        }

        // Image content is passed through as-is so that connectors can decide how to encode it,
        // preserving its binary data and MimeType without serialization.
        if (functionResult is ImageContent imageContent)
        {
